{"command":"python3 <<'PY'
def lev(a,b):
    # simple
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1): dp[i][0]=i
    for j in range(m+1): dp[0][j]=j
    for i in range(1,n+1):
        for j in range(1,m+1):
            cost=0 if a[i-1]==b[j-1] else 1
            dp[i][j]=min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost)
    return dp[n][m]
for cand in ["english","english1k","english10k"]:
    for test in ["English","ENGLISH","eng","engl","englis","english1","english2k","foo"]:
        print(f"{test} vs {cand}: {lev(test,cand)}")
    print("---")
PY"}

