def jaro(s1,s2):
    # https://en.wikipedia.org/wiki/Jaro%E2%80%93Winkler_distance
    if s1==s2:
        return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0:
        return 0.0
    match_dist=max(len1,len2)//2-1
