    k=0
    for i in range(len1):
        if not s1_matches[i]:
            continue
        while not s2_matches[k]:
            k+=1
        if s1[i]!=s2[k]:
            transpositions+=1
        k+=1
    transpositions//=2
    return (matches/len1 + matches/len2 + (matches-transpositions)/matches)/3.0

